    {id:'precinct',name:'BELLWETHER PRECINCT',sub:'MAJOR CRIMES · YOUR OFFICE',x:1085,y:350,color:'#51605a',kind:'precinct',icon:'▥'},
    {id:'morgue',name:'COUNTY MEDICAL EXAMINER',sub:'AUTOPSY WING · RESTRICTED',x:1160,y:685,color:'#53615a',kind:'morgue',icon:'＋'},
    {id:'cemetery',name:'ASHGROVE CEMETERY',sub:'NORTH GATE · 24 HOURS',x:260,y:750,color:'#596450',kind:'cemetery',icon:'†'},
    {id:'archive',name:'OLD COUNTY RECORDS',sub:'BASEMENT STACKS',x:900,y:800,color:'#625c50',kind:'archive',icon:'▤'},
    {id:'apartment',name:'VANE STREET FLATS',sub:'MISSING PERSONS ADDRESS',x:1330,y:510,color:'#69584f',kind:'apartment',icon:'▥'},
    {id:'forest',name:'BLACKWATER TREE LINE',sub:'COUNTY ROAD 9 · NO LIGHTING',x:360,y:990,color:'#465443',kind:'forest',icon:'♧'},
    {id:'bar',name:'THE MERCY ROOM',sub:'CLOSED FOR THE NIGHT',x:950,y:170,color:'#594c48',kind:'bar',icon:'◒'},
    {id:'hospital',name:'BELLWETHER GENERAL',sub:'EMERGENCY DEPARTMENT',x:1400,y:850,color:'#52605e',kind:'hospital',icon:'＋'}
